struct KSShape {
    let sm: CGFloat, md: CGFloat, lg: CGFloat, xl: CGFloat
    static func `for`(_ style: KSStyle) -> KSShape {
        switch style {
        case .pantry: return KSShape(sm: 12, md: 18, lg: 22, xl: 28)
        case .notebook: return KSShape(sm: 4, md: 6, lg: 8, xl: 10)
        case .gallery: return KSShape(sm: 0, md: 2, lg: 2, xl: 4)
        case .atlas: return KSShape(sm: 8, md: 12, lg: 16, xl: 22)
        case .swiss: return KSShape(sm: 0, md: 0, lg: 0, xl: 0)
        }
    }
}

/// Headings per style (see each token file's display.ios).
enum KSFont {
    static func heading(_ style: KSStyle, _ text: Font.TextStyle) -> Font {
        switch style {
        case .pantry: return .custom("BricolageGrotesque-ExtraBold", size: 28, relativeTo: text)
        case .notebook: return .system(text, design: .serif).weight(.semibold)
        case .gallery: return .system(text, design: .serif)
        case .atlas: return .system(text).weight(.semibold)
        case .swiss: return .system(text).weight(.heavy).width(.condensed)
        }
    }
    static let body = Font.body
    static let subhead = Font.subheadline.weight(.medium)
    static let footnote = Font.footnote
    static let caption = Font.caption.weight(.medium)
}

enum KSSpace {
    static let s0: CGFloat = 0
    static let s1: CGFloat = 2
    static let s2: CGFloat = 4
    static let s3: CGFloat = 8
    static let s4: CGFloat = 12
    static let s5: CGFloat = 16
    static let s6: CGFloat = 20
    static let s7: CGFloat = 24
    static let s8: CGFloat = 32
    static let s9: CGFloat = 40
    static let s10: CGFloat = 56
}
